/* eslint-env serviceworker */

/**
 * sw.js - offline shell for the installed app.
 *
 * Deliberately not generated by a build plugin. Vite hashes asset filenames, so a
 * precache manifest would have to be produced at build time and kept in step with
 * the bundle; the alternative used here is a tiny static precache for the things
 * whose URLs never change, plus runtime caching that fills in the hashed bundles the
 * first time they are fetched. The cost is that the very first visit must be online.
 * The benefit is a service worker that cannot go stale against the build.
 *
 * Two strategies, chosen per request kind:
 *   - **Navigations: network first.** A game that silently serves last week's build
 *     because a cache entry outranked the network is a support nightmare. The cached
 *     shell is the offline fallback, not the default.
 *   - **Everything else same-origin: stale-while-revalidate.** Hashed bundles are
 *     immutable, so serving from cache is always correct and the background refresh
 *     costs nothing.
 *
 * Cross-origin requests are not touched at all - model API calls must never be
 * served from a cache.
 */

const VERSION = 'v1';
const SHELL = `blackout-shell-${VERSION}`;
const RUNTIME = `blackout-runtime-${VERSION}`;

/** Only URLs that are stable across builds belong here. */
const PRECACHE = [
  '/',
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/audio/blackout-theme.mp3',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL)
      // Individually, so one 404 does not fail the whole install.
      .then((cache) => Promise.allSettled(PRECACHE.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((key) => key !== SHELL && key !== RUNTIME).map((key) => caches.delete(key)),
      ))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Never let the worker serve itself from a cache - that is how an update gets stuck.
  if (url.pathname === '/sw.js') return;

  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(SHELL).then((cache) => cache.put('/', copy));
          return response;
        })
        .catch(() => caches.match('/').then((cached) => cached || Response.error())),
    );
    return;
  }

  event.respondWith(
    caches.match(request).then((cached) => {
      const network = fetch(request)
        .then((response) => {
          // Opaque and error responses are not worth a cache slot.
          if (response.ok && response.type === 'basic') {
            const copy = response.clone();
            caches.open(RUNTIME).then((cache) => cache.put(request, copy));
          }
          return response;
        })
        .catch(() => cached);

      return cached || network;
    }),
  );
});
